import java.io.InputStream;
import java.io.IOException;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int len = 0;

        private boolean hasNextByte() {
            if (ptr < len) return true;
            ptr = 0;
            try {
                len = in.read(buffer);
            } catch (IOException e) {
                len = -1;
            }
            return len > 0;
        }

        private int readByte() {
            if (hasNextByte()) return buffer[ptr++];
            return -1;
        }

        public int nextInt() {
            int c = readByte();
            while (c <= ' ') {
                if (c == -1) return -1;
                c = readByte();
            }
            int res = 0;
            while (c > ' ') {
                if (c >= '0' && c <= '9') {
                    res = res * 10 + (c - '0');
                }
                c = readByte();
            }
            return res;
        }
    }

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        int n = scanner.nextInt();
        if (n == -1) return;

        int maxEdges = 600005;
        int[] head = new int[n + 1];
        int[] to = new int[maxEdges + 5];
        int[] next = new int[maxEdges + 5];
        int edgeCount = 0;

        for (int i = 1; i <= n; i++) {
            head[i] = -1;
        }

        for (int i = 1; i <= n; i++) {
            int m = scanner.nextInt();
            for (int j = 0; j < m; j++) {
                int v = scanner.nextInt();
                edgeCount++;
                to[edgeCount] = v;
                next[edgeCount] = head[i];
                head[i] = edgeCount;
            }
        }

        int[] color = new int[n + 1];
        int[] queue = new int[n + 5];
        int front = 0, back = 0;

        color[1] = 1;
        queue[back++] = 1;

        while (front < back) {
            int u = queue[front++];
            int c = color[u];
            int nextColor = (c == 1) ? 2 : 1;

            for (int e = head[u]; e != -1; e = next[e]) {
                int v = to[e];
                if (color[v] == 0) {
                    color[v] = nextColor;
                    queue[back++] = v;
                }
            }
        }

        StringBuilder team1 = new StringBuilder();
        StringBuilder team2 = new StringBuilder();

        boolean first1 = true;
        boolean first2 = true;

        for (int i = 1; i <= n; i++) {
            if (color[i] == 1) {
                if (!first1) team1.append(' ');
                team1.append(i);
                first1 = false;
            } else {
                if (!first2) team2.append(' ');
                team2.append(i);
                first2 = false;
            }
        }

        System.out.println(team1.toString());
        System.out.println(team2.toString());
    }
}
